 65→
 66→func (c *Claude) Name() string               { return "claude-code" }
 67→func (c *Claude) Binary() string             { return "claude" }
 68→func (c *Claude) EntireAgent() string        { return "claude-code" }
 69→func (c *Claude) PromptPattern() string      { return `❯` }
