 72→func (c *Claude) IsTransientError(out Output, err error) bool {
 73→	if err == nil {
 74→		return false
 75→	}
 76→	combined := out.Stdout + out.Stderr
 77→	transientPatterns := []string{
 78→		"overloaded",
 79→		"rate limit",
 80→		"529",
 81→		"503",
 82→		"ECONNRESET",
 83→		"ETIMEDOUT",
 84→	}
 85→	for _, p := range transientPatterns {
 86→		if strings.Contains(combined, p) {
 87→			return true
 88→		}
 89→	}
 90→	return false
 91→}
